import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

import '../../services/auth_service.dart';
import '../../theme/app_theme.dart';
import 'register_screen.dart';

/// Logo ISG (PNG encodé en base64) — permet d'afficher le vrai logo de
/// l'école sans dépendre d'un asset packagé séparément, et de garder ce
/// fichier autonome. Toujours posé sur un fond blanc arrondi, comme le
/// veut la charte graphique ISG (même en thème sombre).
const String _kIsgLogoB64 =
'''''';

class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key});

  @override
  State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
  final _emailCtrl = TextEditingController();
  final _passCtrl = TextEditingController();
  final _resetEmailCtrl = TextEditingController();

  final _formKey = GlobalKey<FormState>();

  bool _loading = false;
  bool _hidePass = true;
  String? _error;

  @override
  void dispose() {
    _emailCtrl.dispose();
    _passCtrl.dispose();
    _resetEmailCtrl.dispose();
    super.dispose();
  }

  Future<void> _login() async {
    if (!_formKey.currentState!.validate()) return;

    setState(() {
      _loading = true;
      _error = null;
    });

    final auth = Provider.of<AuthService>(
      context,
      listen: false,
    );

    final err = await auth.login(
      email: _emailCtrl.text.trim(),
      password: _passCtrl.text,
    );

    if (!mounted) return;

    setState(() {
      _loading = false;
      _error = err;
    });
  }

  Future<void> _forgotPassword() async {
    _resetEmailCtrl.text = _emailCtrl.text.trim();

    final email = await showDialog<String>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: const Text(
            'Mot de passe oublié ?',
            style: TextStyle(fontWeight: FontWeight.w800),
          ),
          content: TextField(
            controller: _resetEmailCtrl,
            keyboardType: TextInputType.emailAddress,
            decoration: InputDecoration(
              labelText: 'Email',
              hintText: 'Votre Email',
              prefixIcon: const Icon(
                Icons.email_outlined,
              ),
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(11),
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(dialogContext);
              },
              child: const Text(
                'Annuler',
              ),
            ),
            ElevatedButton(
              onPressed: () {
                final value =
                _resetEmailCtrl.text.trim();

                if (value.isEmpty) {
                  return;
                }

                Navigator.pop(
                  dialogContext,
                  value,
                );
              },
              style: ElevatedButton.styleFrom(
                backgroundColor: AppTheme.isgBlue,
                foregroundColor: Colors.white,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(11),
                ),
              ),
              child: const Text(
                'Envoyer',
              ),
            ),
          ],
        );
      },
    );

    if (email == null || email.isEmpty) {
      return;
    }

    if (!mounted) return;

    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) {
        return AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          content: Row(
            children: [
              const SizedBox(
                width: 22,
                height: 22,
                child: CircularProgressIndicator(
                  strokeWidth: 2.5,
                  color: AppTheme.isgBlue,
                ),
              ),
              const SizedBox(width: 20),
              const Expanded(
                child: Text(
                  "Envoi de l'email…",
                ),
              ),
            ],
          ),
        );
      },
    );

    final auth = Provider.of<AuthService>(
      context,
      listen: false,
    );

    final error = await auth.resetPassword(
      email: email,
    );

    if (!mounted) return;

    Navigator.of(context).pop();

    if (error == null) {
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(
          SnackBar(
            content: const Text(
              'Un email de réinitialisation a été envoyé.',
              style: TextStyle(fontWeight: FontWeight.w600),
            ),
            backgroundColor: const Color(0xff0F9D58),
            behavior: SnackBarBehavior.floating,
          ),
        );
    } else {
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(
          SnackBar(
            content: Text(
              error,
              style: const TextStyle(fontWeight: FontWeight.w600),
            ),
            backgroundColor: const Color(0xffD63A3A),
            behavior: SnackBarBehavior.floating,
          ),
        );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [
              AppTheme.isgBlue,
              AppTheme.isgBlueDark,
              AppTheme.isgOrange,
            ],
            stops: [
              0.0,
              0.55,
              1.0,
            ],
          ),
        ),
        child: SafeArea(
          child: Center(
            child: SingleChildScrollView(
              padding: const EdgeInsets.all(24),
              child: Card(
                elevation: 10,
                shadowColor: AppTheme.isgBlueDark.withValues(alpha: 0.35),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(18),
                ),
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 440),
                  child: Padding(
                    padding: const EdgeInsets.all(24),
                    child: Form(
                      key: _formKey,
                      child: Column(
                        crossAxisAlignment:
                        CrossAxisAlignment.stretch,
                        children: [
                          const Center(
                            child: _IsgLogo(height: 68),
                          ),

                          const SizedBox(height: 16),

                          const Text(
                            'ISG Cours',
                            textAlign: TextAlign.center,
                            style: TextStyle(
                              fontSize: 26,
                              fontWeight: FontWeight.w800,
                              color: AppTheme.isgBlue,
                            ),
                          ),

                          const SizedBox(height: 4),

                          const Text(
                            'Plateforme de partage des cours — ISG Gabès',
                            textAlign: TextAlign.center,
                            style: TextStyle(
                              color: Colors.grey,
                              fontSize: 13,
                            ),
                          ),

                          const SizedBox(height: 24),

                          if (_error != null)
                            Container(
                              margin: const EdgeInsets.only(bottom: 12),
                              padding:
                              const EdgeInsets.all(12),
                              decoration: BoxDecoration(
                                color: const Color(0xffD63A3A).withValues(alpha: 0.10),
                                borderRadius:
                                BorderRadius.circular(
                                  11,
                                ),
                                border: Border.all(
                                  color: const Color(0xffD63A3A).withValues(alpha: 0.25),
                                ),
                              ),
                              child: Row(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  const Icon(
                                    Icons.error_outline_rounded,
                                    color: Color(0xffD63A3A),
                                    size: 20,
                                  ),
                                  const SizedBox(width: 10),
                                  Expanded(
                                    child: Text(
                                      _error!,
                                      style: const TextStyle(
                                        color: Color(0xffD63A3A),
                                        fontSize: 13,
                                        fontWeight: FontWeight.w600,
                                      ),
                                    ),
                                  ),
                                ],
                              ),
                            ),

                          TextFormField(
                            controller: _emailCtrl,
                            keyboardType:
                            TextInputType.emailAddress,
                            decoration: InputDecoration(
                              labelText: 'Email',
                              hintText:
                              'Votre Email',
                              prefixIcon: const Icon(
                                Icons.email_outlined,
                              ),
                              border: OutlineInputBorder(
                                borderRadius: BorderRadius.circular(11),
                              ),
                            ),
                            validator: (v) {
                              if (v == null ||
                                  v.trim().isEmpty) {
                                return 'Email requis';
                              }

                              return null;
                            },
                          ),

                          const SizedBox(height: 12),

                          TextFormField(
                            controller: _passCtrl,
                            obscureText: _hidePass,
                            decoration: InputDecoration(
                              labelText: 'Mot de passe',
                              prefixIcon:
                              const Icon(
                                Icons.lock_outline,
                              ),
                              border: OutlineInputBorder(
                                borderRadius: BorderRadius.circular(11),
                              ),
                              suffixIcon:
                              IconButton(
                                icon: Icon(
                                  _hidePass
                                      ? Icons.visibility
                                      : Icons
                                      .visibility_off,
                                ),
                                onPressed: () {
                                  setState(() {
                                    _hidePass =
                                    !_hidePass;
                                  });
                                },
                              ),
                            ),
                            validator: (v) {
                              if (v == null ||
                                  v.length < 6) {
                                return 'Mot de passe (min 6)';
                              }

                              return null;
                            },
                          ),

                          const SizedBox(height: 4),

                          Align(
                            alignment:
                            Alignment.centerRight,
                            child: TextButton(
                              onPressed: _loading
                                  ? null
                                  : _forgotPassword,
                              style: TextButton.styleFrom(
                                foregroundColor: AppTheme.isgBlue,
                              ),
                              child: const Text(
                                'Mot de passe oublié ?',
                              ),
                            ),
                          ),

                          const SizedBox(height: 8),

                          SizedBox(
                            height: 52,
                            child: ElevatedButton(
                              onPressed:
                              _loading ? null : _login,
                              style: ElevatedButton.styleFrom(
                                backgroundColor: AppTheme.isgOrange,
                                foregroundColor: Colors.white,
                                disabledBackgroundColor:
                                AppTheme.isgOrange.withValues(alpha: 0.45),
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(13),
                                ),
                                elevation: 6,
                                shadowColor: AppTheme.isgOrange.withValues(alpha: 0.35),
                                textStyle: const TextStyle(
                                  fontSize: 16,
                                  fontWeight: FontWeight.w800,
                                ),
                              ),
                              child: _loading
                                  ? const SizedBox(
                                height: 20,
                                width: 20,
                                child:
                                CircularProgressIndicator(
                                  strokeWidth: 2,
                                  color:
                                  Colors.white,
                                ),
                              )
                                  : const Text(
                                'Se connecter',
                              ),
                            ),
                          ),

                          const SizedBox(height: 12),

                          TextButton(
                            onPressed: () {
                              Navigator.push(
                                context,
                                MaterialPageRoute(
                                  builder: (_) =>
                                  const RegisterScreen(),
                                ),
                              );
                            },
                            style: TextButton.styleFrom(
                              foregroundColor: AppTheme.isgBlueDark,
                            ),
                            child: const Text(
                              'Pas de compte ? Créer un compte',
                              style: TextStyle(fontWeight: FontWeight.w600),
                            ),
                          ),

                          const SizedBox(height: 8),


                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

/// Logo ISG affiché sur un fond blanc arrondi, conformément à la charte
/// graphique ("logo toujours posé sur fond blanc arrondi, padding
/// 14-16px, border-radius 14px, même en thème sombre").
class _IsgLogo extends StatelessWidget {
  final double height;
  const _IsgLogo({this.height = 68});

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        boxShadow: [
          BoxShadow(
            color: AppTheme.isgBlue.withValues(alpha: 0.15),
            blurRadius: 16,
            offset: const Offset(0, 6),
          ),
        ],
      ),
      child: Image.memory(
        base64Decode(_kIsgLogoB64),
        height: height,
        fit: BoxFit.contain,
      ),
    );
  }
}